mapper.select:
SELECT 
FROM xxl_ai_todo_effect AS t
WHERE t.id = #{id}

mapper.insert:
INSERT INTO xxl_ai_todo_effect (
	kind, effect_key, payload, generation, attempts, due_time, add_time, update_time
) VALUES (
	#{kind}, #{effectKey}, #{payload}, 0, 0, #{dueTime}, NOW(), NOW()
)

mapper.select:
SELECT 
FROM xxl_ai_todo_effect AS t
WHERE t.kind = #{kind} AND t.effect_key = #{effectKey}

SELECT 
FROM xxl_ai_todo_effect AS t
WHERE t.kind = #{kind}
	AND t.due_time <= #{now}
	AND (t.owner IS NULL OR t.owner_until < #{now})
ORDER BY t.id ASC
LIMIT #{limit}
